// formal_counter.sv — AUTO-EMITTED deterministic reset-safety harness.
// Generated by formal_harness_gen.py from the design's OWN L-layer
// interface + reset branch (design INPUT, §4.05). No chip literal.
// Property: one cycle after reset, each registered output holds the
// exact value the RTL's reset branch assigns it (construction-safe).
`default_nettype none
module formal_counter #(
    parameter BITS = 16
) (input wire clk);
    (* anyseq *) wire reset;
    (* anyseq *) wire valid;
    (* anyseq *) wire [3:0] wstrb;
    (* anyseq *) wire [BITS-1:0] wdata;
    (* anyseq *) wire [BITS-1:0] la_write;
    (* anyseq *) wire [BITS-1:0] la_input;
    wire ready;
    wire [BITS-1:0] rdata;
    wire [BITS-1:0] count;
    counter #(.BITS(BITS)) dut (.clk(clk), .reset(reset), .valid(valid), .wstrb(wstrb), .wdata(wdata), .la_write(la_write), .la_input(la_input), .ready(ready), .rdata(rdata), .count(count));

    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;
    wire rst_active = reset;
    reg rst_active_q = 1'b0;
    always @(posedge clk) rst_active_q <= rst_active;

    property p_reset_safety_1;
        @(posedge clk)
            (f_past_valid && rst_active_q) |-> (ready == '0);
    endproperty
    property p_reset_safety_2;
        @(posedge clk)
            (f_past_valid && rst_active_q) |-> (count == '0);
    endproperty

    a_reset_safety_1: assert property (p_reset_safety_1);
    a_reset_safety_2: assert property (p_reset_safety_2);
endmodule
`default_nettype wire
